@VisibleForTesting
  void writeModuleOutput(Appendable out, JSModule m)
      throws FlagUsageException, IOException {
    if (parsedModuleWrappers == null) {
      parsedModuleWrappers = parseModuleWrappers(
          config.moduleWrapper,
          Lists.newArrayList(
              compiler.getDegenerateModuleGraph().getAllModules()));
    }

    String fileName = getModuleOutputFileName(m);
    String baseName = new File(fileName).getName();
    writeOutput(out, compiler, compiler.toSource(m),
        parsedModuleWrappers.get(m.getName()).replace("%basename%", baseName),
        "%s", null);
  }

public static JSModule[] sortJsModules(Collection<JSModule> modules)
      throws CircularDependencyException {
    // Sort the JSModule in this order.
    List<JSModule> sortedList = (new SortedDependencies<JSModule>(
            Lists.newArrayList(modules))).getSortedList();
    return sortedList.toArray(new JSModule[sortedList.size()]);
  }

private Collection<Definition> lookupDefinitionsForTargetsOfCall(
      Node callsite, DefinitionProvider definitionProvider) {
    Preconditions.checkArgument(callsite.isCall()
        || callsite.isNew());

    Node targetExpression = callsite.getFirstChild();

    // NameReferenceGraph throws an exception unless the node is
    // a GETPROP or a NAME
    if (!useNameReferenceGraph
        || (targetExpression.isGetProp()
        ||  targetExpression.isName())) {

      Collection<Definition> definitions =
        definitionProvider.getDefinitionsReferencedAt(targetExpression);

      if (definitions != null && !definitions.isEmpty()) {
        return definitions;
      }
    }

    return null;
  }

